"""Temperature conversion."""


def celsius_to_fahrenheit(c):
    if not isinstance(c, (int, float)) or isinstance(c, bool):
        raise TypeError("Input must be an int or float.")
    if c < -273.15:
        raise ValueError("Temperature cannot be below absolute zero (-273.15 °C).")
    return c * 9 / 5 + 32

from temperature import celsius_to_fahrenheit

def test():
    # Valid cases
    assert celsius_to_fahrenheit(0) == 32
    assert celsius_to_fahrenheit(100) == 212
    assert celsius_to_fahrenheit(-273.15) == -459.67

    # Invalid types
    try:
        celsius_to_fahrenheit("0")
    except TypeError:
        pass
    else:
        raise AssertionError("Should have raised TypeError for string")

    try:
        celsius_to_fahrenheit(True)
    except TypeError:
        pass
    else:
        raise AssertionError("Should have raised TypeError for bool")

    # Invalid value
    try:
        celsius_to_fahrenheit(-273.16)
    except ValueError:
        pass
    else:
        raise AssertionError("Should have raised ValueError for below absolute zero")

    print("All tests passed!")

if __name__ == "__main__":
    test()

